const $=id=>document.getElementById(id),canvas=$('card'),ctx=canvas.getContext('2d');
const photo=new Image();let ready=false;
const gold='#ab803d',wine='#813923',ink='#49352d';
function text(t,x,y,size,font='Cormorant',color=ink,weight='400'){ctx.fillStyle=color;ctx.font=`${weight} ${size}px "${font}"`;ctx.textAlign='center';ctx.fillText(t,x,y)}
function line(x,y,x2,y2,color=gold,width=1){ctx.strokeStyle=color;ctx.lineWidth=width;ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x2,y2);ctx.stroke()}
function leaf(x,y,s,angle){ctx.save();ctx.translate(x,y);ctx.rotate(angle);ctx.fillStyle='#a3aa8a';ctx.beginPath();ctx.ellipse(0,0,s*.34,s,0,0,Math.PI*2);ctx.fill();ctx.restore()}
function branch(x,y,flip=1){ctx.save();ctx.translate(x,y);ctx.scale(flip,1);ctx.globalAlpha=.55;ctx.strokeStyle='#909475';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(0,0);ctx.quadraticCurveTo(40,-110,12,-230);ctx.stroke();for(let i=0;i<6;i++){leaf(14+i*2,-25-i*31,22,-.7);leaf(32,-40-i*29,20,.8)}ctx.restore()}
function draw(){if(!ready)return;ctx.setTransform(2.4,0,0,2.4,0,0);ctx.fillStyle='#fffaf2';ctx.fillRect(0,0,1000,1250);
const bg=ctx.createLinearGradient(0,0,1000,700);bg.addColorStop(0,'#f5e1d7');bg.addColorStop(.5,'#fffdf7');bg.addColorStop(1,'#eedbcc');ctx.fillStyle=bg;ctx.fillRect(0,0,1000,550);
ctx.strokeStyle='#b78e50';ctx.lineWidth=1.2;ctx.strokeRect(24,24,952,1202);ctx.strokeStyle='#d9c7a8';ctx.strokeRect(31,31,938,1188);
// Display the supplied photograph directly; only the frame crops it. No retouching.
ctx.save();ctx.beginPath();ctx.roundRect(255,48,490,480,[240,240,8,8]);ctx.clip();ctx.drawImage(photo,0,0,photo.width,photo.height,255,48,490,676);ctx.restore();ctx.strokeStyle='#c5a16a';ctx.lineWidth=2;ctx.beginPath();ctx.roundRect(248,41,504,494,[247,247,12,12]);ctx.stroke();
branch(100,520);branch(900,520,-1);text('A DAY FULL OF LITTLE WONDERS',500,576,23,'Georgia',gold);text('Nicole’s',500,709,150,'Great Vibes',wine);text('BIRTHDAY CELEBRATION',500,755,40,'Cormorant',gold,'600');line(380,780,470,780);line(530,780,620,780);text('♡',500,790,28,'Georgia',gold);
text('Benny and Ameri with great pleasure invite',500,832,40);ctx.fillStyle='#f7e3dc';ctx.beginPath();ctx.roundRect(90,853,820,88,44);ctx.fill();ctx.strokeStyle='#c5a16a';ctx.lineWidth=1;ctx.stroke();
let name=$('guest').value.trim()||'Your guest’s name',size=Number($('size').value),font=$('font').value;ctx.font=`${size}px "${font}"`;let fitted=Math.min(size,size*750/Math.max(ctx.measureText(name).width,1));text(name,500,910,fitted,font,wine,font==='Georgia'?'400':'500');$('sizeValue').textContent=`${size} px`;$('fitStatus').textContent=fitted<size-.5?`Adjusted to ${Math.floor(fitted)} px to keep the whole name inside the card.`:'Your name fits beautifully.';
text('to celebrate Nicole’s special day',500,983,40);line(500,1010,500,1110,'#c7ae82');text('SATURDAY',275,1029,25,'Georgia',gold);text('24 October 2026',275,1070,42);text('5:00 PM',275,1107,33);text('THE VENUE',725,1029,25,'Georgia',gold);text('Benny’s Home',725,1070,42);text('Kirombe',725,1107,33);line(320,1131,680,1131,'#d8c3a0');text('Please join us for a joyful evening',500,1174,46,'Great Vibes',wine);text('of love, laughter, and celebration.',500,1214,44,'Great Vibes',wine);
branch(58,1200);branch(942,1200,-1);canvas.setAttribute('aria-label',`Invitation for ${name}. Nicole’s birthday, Saturday 24 October 2026, 5 PM, Benny’s Home, Kirombe.`);
}
for(const id of ['guest','size','font'])$(id).addEventListener('input',draw);
$('fit').onclick=()=>{ctx.font=`52px "${$('font').value}"`;const width=ctx.measureText($('guest').value.trim()||'Your guest’s name').width;$('size').value=Math.max(20,Math.min(64,Math.floor(52*750/width)));draw()};
$('reset').onclick=()=>{$('guest').value='Opakrwoth Jonathan';$('size').value=52;$('font').value='Cormorant';$('status').textContent='';draw()};
$('download').onclick=()=>{draw();$('download').disabled=true;canvas.toBlob(blob=>{if(!blob){$('status').textContent='Could not create the image. Please try again.';$('download').disabled=false;return}const a=document.createElement('a'),url=URL.createObjectURL(blob);a.href=url;const name=$('guest').value.trim().replace(/[^\p{L}\p{N} -]/gu,'').slice(0,70)||'guest';a.download=`Nicole-birthday-${name}.png`;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);$('status').textContent='Your invitation is ready — check your downloads.';$('download').disabled=false},'image/png')};
Promise.all([document.fonts.load('52px Cormorant'),document.fonts.load('150px "Great Vibes"'),new Promise((resolve,reject)=>{photo.onload=resolve;photo.onerror=reject;photo.src='assets/nicole-original.jpg'})]).then(()=>{ready=true;draw();$('download').disabled=false}).catch(()=>{$('status').textContent='The photo or fonts could not load. Please refresh to try again.'});
